local GrainProbeMaker = {}
local PRODUCTS = {
    iron_grainprobe = { name = "Železni sonda za zito", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sonda za zito za mlinarje." },
    bronze_grainprobe = { name = "Bronast sonda za zito", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sonda za zito za mlinarje." },
    silver_grainprobe = { name = "Srebrn sonda za zito", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sonda za zito za mlinarje." },
    gilded_grainprobe = { name = "Pozlačen sonda za zito", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sonda za zito za mlinarje." },
    jewel_set_grainprobe = { name = "Draguljast sonda za zito", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sonda za zito za mlinarje." },
    royal_sovereign_grainprobe = { name = "Kraljevski suveren sonda za zito", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sonda za zito z biseri za krono." },
}
local BUILDINGS = {
    grainprobe_workshop = { name = "Grainprobe delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    grainprobe_house = { name = "Grainprobe hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_grainprobe_atelier = { name = "Mojstrski grainprobe atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_grainprobe_palace = { name = "Suverena grainprobe palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GrainProbeMaker.ironStock = 18; GrainProbeMaker.bronzeStock = 14; GrainProbeMaker.woodStock = 8; GrainProbeMaker.leatherStock = 8; GrainProbeMaker.silverStock = 8; GrainProbeMaker.goldStock = 6; GrainProbeMaker.jewelStock = 4; GrainProbeMaker.pearlStock = 4
GrainProbeMaker.productStock = {}; GrainProbeMaker.buildings = {}; GrainProbeMaker.maker = nil; GrainProbeMaker.activeMaking = {}; GrainProbeMaker.totalProducts = 0; GrainProbeMaker.dayTimer = 0
function GrainProbeMaker.init() GrainProbeMaker.ironStock=18; GrainProbeMaker.bronzeStock=14; GrainProbeMaker.woodStock=8; GrainProbeMaker.leatherStock=8; GrainProbeMaker.silverStock=8; GrainProbeMaker.goldStock=6; GrainProbeMaker.jewelStock=4; GrainProbeMaker.pearlStock=4; GrainProbeMaker.productStock={}; GrainProbeMaker.buildings={}; GrainProbeMaker.maker=nil; GrainProbeMaker.activeMaking={}; GrainProbeMaker.totalProducts=0; GrainProbeMaker.dayTimer=0; print("[GrainProbeMaker] Royal Grain Probe Maker System initialized (6 products, 4 buildings)") end
function GrainProbeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainProbeMaker.maker={name=n or ("Sondar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sondar najet: %s (spretnost: %d)",GrainProbeMaker.maker.name,s),"success") end; return true end
function GrainProbeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainProbeMaker.build(id) local ok,e=GrainProbeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainProbeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainProbeMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainProbeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainProbeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainProbeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainProbeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainProbeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainProbeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainProbeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainProbeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainProbeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainProbeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainProbeMaker.buildings==0 then return false,"Potrebna sondalna delavnica" end; if not GrainProbeMaker.maker then return false,"Potreben sondar" end; return true end
function GrainProbeMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainProbeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainProbeMaker.ironStock=GrainProbeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainProbeMaker.bronzeStock=GrainProbeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainProbeMaker.woodStock=GrainProbeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainProbeMaker.leatherStock=GrainProbeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainProbeMaker.silverStock=GrainProbeMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainProbeMaker.goldStock=GrainProbeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainProbeMaker.jewelStock=GrainProbeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainProbeMaker.pearlStock=GrainProbeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainProbeMaker.maker then t=math.max(1,t-math.floor(GrainProbeMaker.maker.skill/13)) end; table.insert(GrainProbeMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainProbeMaker.completeMaking(m) local q=1.0+(GrainProbeMaker.getQualityBonus()/100); if GrainProbeMaker.maker then q=q+(GrainProbeMaker.maker.skill/140) end; q=math.min(2.5,q); GrainProbeMaker.productStock[m.productType]=(GrainProbeMaker.productStock[m.productType] or 0)+m.quantity; GrainProbeMaker.totalProducts=GrainProbeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainProbeMaker.maker then GrainProbeMaker.maker.itemsMade=GrainProbeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainProbeMaker.maker.skill=math.min(100,GrainProbeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sonda izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function GrainProbeMaker.update(dt) if not _G.state then return end; GrainProbeMaker.dayTimer=GrainProbeMaker.dayTimer+dt; if GrainProbeMaker.dayTimer>=30 then GrainProbeMaker.dayTimer=0; for i=#GrainProbeMaker.activeMaking,1,-1 do local m=GrainProbeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainProbeMaker.completeMaking(m); table.remove(GrainProbeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainProbeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainProbeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainProbeMaker.getStats() return {ironStock=GrainProbeMaker.ironStock,bronzeStock=GrainProbeMaker.bronzeStock,woodStock=GrainProbeMaker.woodStock,leatherStock=GrainProbeMaker.leatherStock,silverStock=GrainProbeMaker.silverStock,goldStock=GrainProbeMaker.goldStock,jewelStock=GrainProbeMaker.jewelStock,pearlStock=GrainProbeMaker.pearlStock,productStock=GrainProbeMaker.productStock,numBuildings=#GrainProbeMaker.buildings,hasMaker=GrainProbeMaker.maker~=nil,makerName=GrainProbeMaker.maker and GrainProbeMaker.maker.name or "—",makerSkill=GrainProbeMaker.maker and GrainProbeMaker.maker.skill or 0,activeMaking=#GrainProbeMaker.activeMaking,totalProducts=GrainProbeMaker.totalProducts} end
return GrainProbeMaker
